module.exports = local_settings

// this device's settings as synced keys: dconf keys from the allowed dirs + /extensions/<uuid>
function local_settings ({ dconf, extensions, rules }) {
  const api = { read_all, write, dump: () => dconf.dump('/') }
  return api

  async function read_all () {
    const all = await extensions.read_all()
    for (const dir of rules.allowed_dirs) Object.assign(all, await dconf.read_dir(dir))
    return all
  }

  // null means reset (for an extension: disable)
  function write (key, value) {
    if (extensions.owns(key)) return extensions.write(key, value)
    return value === null ? dconf.reset(key) : dconf.write(key, value)
  }
}
